<template><scroll-view scroll-y class="original-subpage" :class="{'kx-dark':prefs.theme==='dark','kx-care':prefs.care}" :style="mobilePreferenceStyle(prefs)"><text class="op-back" @click="uni.navigateBack()">‹ {{$t('m2.mobile.back')}}</text><view class="op-title">{{$t('v15.mobileAdmin')}}</view><view class="v15-notice">{{$t('v15.adminScope')}}</view><view v-if="busy" class="op-empty">{{$t('account.loading')}}</view><view v-if="error" class="op-error">{{error}}<button class="op-action op-secondary" @click="load">{{$t('v15.retry')}}</button></view><template v-if="authorized&&stats"><view class="v15-columns"><view v-for="v in values" :key="v.key" class="op-card"><text class="op-muted">{{$t(v.label)}}</text><view class="op-card-title">{{v.value}}</view></view></view><template v-if="records"><view class="v15-choices"><view v-for="(tab,i) in tabs" :key="tab" class="v15-choice" :class="{selected:active===tab}" @click="active=tab">{{$t(labels[i])}} · {{records[tab].length}}</view></view><view v-for="(r,i) in rows" :key="String(r.id||i)" class="op-card"><view class="v14-between"><text class="op-card-title">{{title(r)}}</text><text class="v14-status">{{status(r)}}</text></view><text class="op-muted">{{String(r.id||'')}}</text></view><view v-if="!rows.length" class="op-empty">{{$t('v15.noRows')}}</view></template><button class="op-action op-secondary" @click="load">{{$t('v15.refresh')}}</button></template></scroll-view></template>
